#!/usr/bin/env node
/**
 * KAWSAY — one-time band key fetcher (P1).
 *
 * Xiaomi/Huami bands (Mi Band 4/5/6, Amazfit) never reveal their pairing key over
 * Bluetooth: the connection handshake only proves the app already knows the key. The key
 * is generated by Xiaomi when the band is first bound and kept on Xiaomi's servers. So to
 * let KAWSAY talk to the band directly — with no Xiaomi app running — you fetch that key
 * ONCE from your account here. Afterwards KAWSAY ↔ band is pure Bluetooth, no internet.
 *
 * This runs on your own computer and talks only to Zepp's servers. Your password is sent
 * encrypted to Zepp exactly as the official app sends it, and is never stored or logged.
 *
 * Usage (needs Node 20+ and internet, once):
 *   node tools/get-band-key.mjs
 *   node tools/get-band-key.mjs --email you@example.com --password 'secret'
 *
 * Works when the band is bound to a Zepp / Zepp Life / Amazfit account with an email and
 * password. If your band is bound to a Xiaomi account (phone-number or Xiaomi login), use
 * the browser method in tools/README-band-key.md instead.
 *
 * HTTP flow reimplemented from the MIT-licensed huami-token
 * (https://codeberg.org/argrento/huami-token, © 2025 Kirill Snezhko). No code was copied.
 */
import { createCipheriv, randomUUID, randomBytes } from 'node:crypto';
import { createInterface } from 'node:readline/promises';
import { stdin, stdout, argv } from 'node:process';

const ZEPP = {
  tokens: 'https://api-user-us2.zepp.com/v2/registrations/tokens',
  login: 'https://api-mifit-us2.zepp.com/v2/client/login',
  devices: (userId) => `https://api-mifit.zepp.com/users/${userId}/devices`,
};
// Fixed key/iv the Zepp app uses to wrap the login payload (public, from the app).
const ENC_KEY = Buffer.from('xeNtBVqzDc6tuNTh');
const ENC_IV = Buffer.from('MAAAYAAAAAAAAABg');

const form = (obj) =>
  Object.entries(obj)
    .flatMap(([k, v]) => (Array.isArray(v) ? v.map((x) => [k, x]) : [[k, v]]))
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
    .join('&');

function encryptPayload(text) {
  const cipher = createCipheriv('aes-128-cbc', ENC_KEY, ENC_IV); // PKCS#7 padding on by default
  return Buffer.concat([cipher.update(Buffer.from(text, 'utf8')), cipher.final()]);
}

async function getAccessToken(email, password) {
  const body = encryptPayload(
    form({
      emailOrPhone: email,
      state: 'REDIRECTION',
      client_id: 'HuaMi',
      password,
      redirect_uri: 'https://s3-us-west-2.amazonaws.com/hm-registration/successsignin.html',
      region: 'us-west-2',
      token: ['access', 'refresh'],
      country_code: 'US',
    }),
  );
  const res = await fetch(ZEPP.tokens, {
    method: 'POST',
    redirect: 'manual',
    headers: {
      appname: 'com.huami.midong',
      app_name: 'com.huami.midong',
      cv: '151689_9.12.5',
      v: '2.0',
      appplatform: 'android_phone',
      vn: '9.12.5',
      'x-hm-ekv': '1',
      'user-agent': 'Zepp/9.12.5 (Pixel 4; Android 12; Density/2.75)',
      'content-type': 'application/x-www-form-urlencoded; charset=UTF-8',
    },
    body,
  });
  const location = res.headers.get('location');
  if (res.status !== 303 || !location) {
    throw new Error(`Login was not accepted (HTTP ${res.status}). Check the email and password, or use the browser method.`);
  }
  const access = new URL(location).searchParams.get('access');
  if (!access) throw new Error(location.includes('error') ? 'Zepp rejected the sign-in (wrong email or password).' : 'No access token in the Zepp reply.');
  return access;
}

async function login(access) {
  const res = await fetch(ZEPP.login, {
    method: 'POST',
    headers: {
      appname: 'com.huami.webapp',
      app_name: 'com.huami.webapp',
      'content-type': 'application/x-www-form-urlencoded; charset=UTF-8',
      'user-agent': 'Mozilla/5.0 (X11; Linux x86_64; rv:133.0) Gecko/20100101 Firefox/133.0',
    },
    body: form({
      code: access,
      device_id: randomUUID(),
      device_model: 'android_phone',
      app_version: '9.12.5',
      third_name: 'huami',
      app_name: 'com.huami.midong',
      country_code: 'US',
      grant_type: 'access_token',
      allow_registration: 'false',
      lang: 'en',
    }),
  });
  if (!res.ok) throw new Error(`Zepp login failed (HTTP ${res.status}).`);
  const info = (await res.json()).token_info ?? {};
  if (!info.app_token || !info.user_id) throw new Error('Zepp did not return an app token.');
  return { appToken: info.app_token, userId: info.user_id };
}

async function getDevices({ appToken, userId }) {
  const params = new URLSearchParams({
    userid: userId,
    appid: String(randomBytes(8).readBigUInt64BE()),
    country: 'US',
    cv: '151689_9.12.5',
    device: 'android_32',
    device_type: 'android_phone',
    enableMultiDevice: 'true',
    lang: 'en_US',
    v: '2.0',
  });
  params.append('r', randomUUID());
  const res = await fetch(`${ZEPP.devices(userId)}?${params}`, {
    headers: {
      appname: 'com.huami.midong',
      apptoken: appToken,
      country: 'US',
      cv: '151689_9.12.5',
      v: '2.0',
      'user-agent': 'Zepp/9.12.5 (Pixel 4; Android 12; Density/2.75)',
    },
  });
  if (!res.ok) throw new Error(`Could not list devices (HTTP ${res.status}).`);
  const items = (await res.json()).items ?? [];
  return items.map((d) => {
    let authKey = null;
    try {
      authKey = JSON.parse(d.additionalInfo ?? '{}').auth_key ?? null;
    } catch {
      authKey = null;
    }
    return { mac: d.macAddress ?? '??', active: Boolean(d.activeStatus), name: d.deviceSource ?? d.deviceType ?? 'device', authKey };
  });
}

function arg(name) {
  const i = argv.indexOf(`--${name}`);
  return i !== -1 ? argv[i + 1] : undefined;
}

async function main() {
  let email = arg('email');
  let password = arg('password');
  if (!email || !password) {
    const rl = createInterface({ input: stdin, output: stdout });
    email ??= await rl.question('Zepp / Zepp Life / Amazfit email: ');
    password ??= await rl.question('Password (hidden input is not available here): ');
    rl.close();
  }

  process.stdout.write('\nTalking to Zepp…\n');
  const devices = await getDevices(await login(await getAccessToken(email.trim(), password)));
  const bands = devices.filter((d) => d.authKey && /^[0-9a-f]{32}$/i.test(d.authKey));
  if (bands.length === 0) {
    process.stdout.write('\nSigned in, but found no band with a key on this account.\n');
    process.stdout.write('Make sure the band is bound in this Zepp account, or use the browser method in tools/README-band-key.md.\n');
    return;
  }
  process.stdout.write('\nFound your band key. Paste it into KAWSAY → Connect → Band key:\n\n');
  for (const b of bands) {
    process.stdout.write(`  ${b.mac}${b.active ? '' : ' (not active)'}\n  0x${b.authKey.toLowerCase()}\n\n`);
  }
  process.stdout.write('Keep this key private. After this, KAWSAY needs only Bluetooth — no internet, no Xiaomi app.\n');
}

main().catch((e) => {
  process.stderr.write(`\n${e.message}\n`);
  process.stderr.write('If your band is on a Xiaomi (phone) account, use the browser method in tools/README-band-key.md.\n');
  process.exitCode = 1;
});
